public sealed class RichNotesWindow : Window {
 private RichNote _note;private readonly TextBox _editor=new(){AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,FontSize=14,MinHeight=300};
 private readonly StackPanel _preview=new(){Spacing=2};private readonly TextBlock _status=new(){FontSize=11,Foreground=DesignTokens.Secondary};
 private readonly Stack<RichNote> _undo=new(),_redo=new();private bool _updating;private TextFormat? _painter,_typing;
 public RichNote Note=>_note;
 public TextBox Editor=>_editor;
 public RichNotesWindow(string title,RichNote note){_note=note.Copy();Title=title;Width=1150;Height=760;MinWidth=850;MinHeight=550;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=DesignTokens.Background;
  var root=new DockPanel{Margin=new Thickness(18)};var heading=new TextBlock{Text=title,FontSize=22,FontWeight=FontWeight.SemiBold,Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);
  var toolbar=new WrapPanel{ItemSpacing=5,LineSpacing=5,Margin=new Thickness(0,0,0,12)};
  Button Command(string name,Action action){var b=new Button{Content=name,MinHeight=30,Padding=new Thickness(8,4)};b.Click+=(_,_)=>{try{action();_editor.Focus();}catch(Exception e){_status.Text=e.Message;}};toolbar.Children.Add(b);return b;}
  Command("B",()=>Format(f=>f with{Bold=f.Bold!=true})).FontWeight=FontWeight.Bold;Command("I",()=>Format(f=>f with{Italic=!f.Italic})).FontStyle=FontStyle.Italic;Command("U",()=>Format(f=>f with{Underline=f.Underline=="None"?"Single":"None"}));
  var font=Command("Font & style…",()=>{});font.Click+=async(_,_)=>{var edit=await new TextFormatWindow(Current(),forNotes:true).ShowDialog<TextFormat?>(this);if(edit!=null)Format(_=>edit);};
  var color=Command("Text color…",()=>{});color.Click+=async(_,_)=>{var choice=await new OfficeColorWindow("Text color",Current().Foreground).ShowDialog<ColorChoice?>(this);if(choice!=null)Format(f=>f with{Foreground=choice.Color});};
  var highlight=Command("Highlight…",()=>{});highlight.Click+=async(_,_)=>{var choice=await new OfficeColorWindow("Highlight",Current().Highlight).ShowDialog<ColorChoice?>(this);if(choice!=null)Format(f=>f with{Highlight=choice.Color});};
  Command("Format Painter",()=>{_painter=Current();_status.Text="Select destination text, then Apply Painter.";});Command("Apply Painter",()=>{if(_painter==null)throw new InvalidOperationException("Copy a format first.");Format(_=>_painter);});Command("Clear",()=>Format(_=>new()));
  var paragraph=Command("Paragraph…",()=>{});paragraph.Click+=async(_,_)=>{int start=ParagraphStart();var edit=await new ParagraphFormatWindow(_note.Paragraphs.GetValueOrDefault(start)??new()).ShowDialog<ParagraphFormat?>(this);if(edit!=null){Checkpoint();foreach(int offset in SelectedParagraphs())_note.Paragraphs[offset]=edit;Render();}};
  Command("• Bullets",()=>List(false));Command("1. Numbering",()=>List(true));Command("Uppercase",()=>Case(true));Command("Lowercase",()=>Case(false));Command("Undo",Undo);Command("Redo",Redo);
  var export=Command("Export HTML…",()=>{});export.Click+=async(_,_)=>{var file=await StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions{Title="Export formatted notes",DefaultExtension="html",SuggestedFileName="Project-notes.html"});if(file?.TryGetLocalPath()is string path){using var stream=new FileStream(path,FileMode.CreateNew);using var writer=new StreamWriter(stream);writer.Write(_note.Html());_status.Text="Formatted notes exported.";}};
  DockPanel.SetDock(toolbar,Dock.Top);root.Children.Add(toolbar);
  var footer=new DockPanel{Margin=new Thickness(0,12,0,0)};var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};var cancel=new Button{Content="Cancel"};cancel.Click+=(_,_)=>Close(null);var apply=new Button{Content="Apply"};apply.Classes.Add("primary");apply.Click+=(_,_)=>Close(_note.Copy());actions.Children.Add(cancel);actions.Children.Add(apply);DockPanel.SetDock(actions,Dock.Right);footer.Children.Add(actions);footer.Children.Add(_status);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
  var split=new Grid{ColumnDefinitions=new ColumnDefinitions("*,12,*")};var input=new DockPanel();var inputLabel=new TextBlock{Text="EDIT TEXT",FontSize=10,Foreground=DesignTokens.Secondary,Margin=new Thickness(0,0,0,6)};DockPanel.SetDock(inputLabel,Dock.Top);input.Children.Add(inputLabel);input.Children.Add(_editor);split.Children.Add(input);
  var rendered=new DockPanel();var renderLabel=new TextBlock{Text="FORMATTED PREVIEW",FontSize=10,Foreground=DesignTokens.Secondary,Margin=new Thickness(0,0,0,6)};DockPanel.SetDock(renderLabel,Dock.Top);rendered.Children.Add(renderLabel);rendered.Children.Add(new Border{Background=DesignTokens.Surface,CornerRadius=new CornerRadius(12),Padding=new Thickness(18),Child=new ScrollViewer{Content=_preview}});Grid.SetColumn(rendered,2);split.Children.Add(rendered);root.Children.Add(split);Content=root;
  _editor.Text=_note.Text;_editor.TextChanged+=(_,_)=>{if(_updating)return;var next=_editor.Text??"";if(next==_note.Text)return;Checkpoint();int prefix=0;while(prefix<Math.Min(next.Length,_note.Text.Length)&&next[prefix]==_note.Text[prefix])prefix++;int inserted=next.Length-_note.Text.Length;_note.ReplaceText(next);if(_typing!=null&&inserted>0)_note.Format(prefix,inserted,_=>_typing);Render();};
  AddHandler(InputElement.KeyDownEvent,(_,e)=>{if(!e.KeyModifiers.HasFlag(OperatingSystem.IsMacOS()?KeyModifiers.Meta:KeyModifiers.Control))return;if(e.Key==Key.B){e.Handled=true;Format(f=>f with{Bold=f.Bold!=true});}else if(e.Key==Key.I){e.Handled=true;Format(f=>f with{Italic=!f.Italic});}else if(e.Key==Key.U){e.Handled=true;Format(f=>f with{Underline=f.Underline=="None"?"Single":"None"});}else if(e.Key==Key.Z){e.Handled=true;Undo();}else if(e.Key==Key.Y){e.Handled=true;Redo();}},Avalonia.Interactivity.RoutingStrategies.Tunnel);Render();
 }
 private (int Start,int Length) Range(){int a=Math.Min(_editor.SelectionStart,_editor.SelectionEnd),b=Math.Max(_editor.SelectionStart,_editor.SelectionEnd);if(a==b){while(a>0&&char.IsLetterOrDigit(_note.Text[a-1]))a--;while(b<_note.Text.Length&&char.IsLetterOrDigit(_note.Text[b]))b++;}return(a,b-a);}
 private TextFormat Current()=>_note.FormatAt(Math.Clamp(_editor.SelectionStart,0,Math.Max(0,_note.Text.Length-1)));
 public void Format(Func<TextFormat,TextFormat> edit){var range=Range();if(range.Length==0){_typing=edit(_typing??Current()).Checked();_status.Text="Style set for the next text you type.";return;}Checkpoint();_note.Format(range.Start,range.Length,edit);Render();}
 private void Checkpoint(){_undo.Push(_note.Copy());_redo.Clear();if(_undo.Count>100){var items=_undo.Take(100).Reverse().ToArray();_undo.Clear();foreach(var item in items)_undo.Push(item);}}
 public void Undo(){if(_undo.Count==0)return;_redo.Push(_note.Copy());_note=_undo.Pop();Sync();}
 public void Redo(){if(_redo.Count==0)return;_undo.Push(_note.Copy());_note=_redo.Pop();Sync();}
 private void Sync(){int caret=Math.Min(_editor.CaretIndex,_note.Text.Length);_updating=true;_editor.Text=_note.Text;_editor.CaretIndex=caret;_updating=false;Render();}
 private int ParagraphStart(){int caret=Math.Clamp(Math.Min(_editor.SelectionStart,_editor.SelectionEnd),0,_note.Text.Length);return caret==0?0:_note.Text.LastIndexOf('\n',caret-1)+1;}
 private IEnumerable<int> SelectedParagraphs(){int a=ParagraphStart(),end=Math.Max(_editor.SelectionStart,_editor.SelectionEnd);yield return a;while(a<_note.Text.Length){int line=_note.Text.IndexOf('\n',a);if(line<0||line+1>end)break;a=line+1;yield return a;}}
 private void List(bool numbered){Checkpoint();var starts=SelectedParagraphs().ToArray();int number=starts.Length;foreach(int start in starts.Reverse()){string prefix=numbered?(number--).ToString(CultureInfo.InvariantCulture)+". ":"• ";_note.ReplaceText(_note.Text.Insert(start,prefix));}Sync();}
 private void Case(bool upper){var r=Range();if(r.Length==0)return;Checkpoint();var text=_note.Text;var replacement=upper?text.Substring(r.Start,r.Length).ToUpperInvariant():text.Substring(r.Start,r.Length).ToLowerInvariant();var runs=_note.Runs.ToList();_note.ReplaceText(text[..r.Start]+replacement+text[(r.Start+r.Length)..]);if(replacement.Length==r.Length)_note.Runs=runs;Sync();}
 public void Render(){_preview.Children.Clear();int offset=0;foreach(var paragraph in _note.Text.Split('\n')){
  var p=_note.Paragraphs.GetValueOrDefault(offset)??new();var block=new TextBlock{TextWrapping=TextWrapping.Wrap,FontFamily=DesignTokens.Font,FontSize=14,TextAlignment=Enum.Parse<TextAlignment>(p.Alignment),LineHeight=_note.Runs.Where(r=>r.Start<offset+paragraph.Length&&r.Start+r.Length>offset).Select(r=>r.Format.Size??14).DefaultIfEmpty(14).Max()*Math.Clamp(p.LineSpacing,1,3),Margin=new Thickness(Math.Clamp(p.Indent,0,240),p.Before,0,p.After)};
  block.LetterSpacing=_note.FormatAt(offset).Spacing;if(p.FirstLine>0)block.Inlines!.Add(new InlineUIContainer{Child=new Border{Width=p.FirstLine,Height=1}});if(paragraph.Length==0)block.Text=" ";for(int i=0;i<paragraph.Length;){var format=_note.FormatAt(offset+i);int end=i+1;while(end<paragraph.Length&&_note.FormatAt(offset+end)==format)end++;var run=new Run{Text=format.Caps=="Normal"?paragraph[i..end]:paragraph[i..end].ToUpperInvariant(),FontFamily=format.Family!=null?new FontFamily(format.Family):DesignTokens.Font,FontSize=(format.Size??14)*(format.Caps=="Small caps"?.8:1),FontWeight=format.Bold==true?FontWeight.Bold:FontWeight.Normal,FontStyle=format.Italic?FontStyle.Italic:FontStyle.Normal,Foreground=FormatVisuals.Brush(format.Foreground,DesignTokens.Text),Background=FormatVisuals.Brush(format.Highlight,Brushes.Transparent),TextDecorations=FormatVisuals.Decorations(format),BaselineAlignment=format.Vertical=="Superscript"?BaselineAlignment.Superscript:format.Vertical=="Subscript"?BaselineAlignment.Subscript:BaselineAlignment.Baseline};if(format.Caps=="Small caps"){foreach(char character in paragraph[i..end])block.Inlines!.Add(new Run{Text=char.ToUpperInvariant(character).ToString(),FontFamily=run.FontFamily,FontSize=(format.Size??14)*(char.IsLower(character)?.8:1),FontWeight=run.FontWeight,FontStyle=run.FontStyle,Foreground=run.Foreground,Background=run.Background,TextDecorations=run.TextDecorations,BaselineAlignment=run.BaselineAlignment});}else block.Inlines!.Add(run);i=end;}
  _preview.Children.Add(new Border{Background=FormatVisuals.Brush(p.Shading,Brushes.Transparent),BorderBrush=FormatVisuals.Brush(p.Border,Brushes.Transparent),BorderThickness=new Thickness(p.Border!=null?1:0),Child=block});offset+=paragraph.Length+1;
 }_status.Text=$"{_note.Text.Length} characters · {_note.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Length} words · Formatting saved in Planora's companion file.";}
}
public sealed class ParagraphFormatWindow : EditorForm<ParagraphFormat> {
 private readonly ComboBox _alignment;private readonly NumericUpDown _indent,_first,_lines,_before,_after;private readonly TextBox _shade,_border;
 public ParagraphFormatWindow(ParagraphFormat p):base("Paragraph"){Height=650;_alignment=new(){ItemsSource=new[]{"Left","Center","Right","Justify"},SelectedItem=p.Alignment};NumericUpDown Number(double value,decimal min,decimal max)=>new(){Minimum=min,Maximum=max,Value=(decimal)value,Increment=1};_indent=Number(p.Indent,0,240);_first=Number(p.FirstLine,-120,240);_lines=Number(p.LineSpacing,1,3);_lines.Increment=.1m;_before=Number(p.Before,0,60);_after=Number(p.After,0,60);_shade=new(){Text=p.Shading??""};_border=new(){Text=p.Border??""};Field("Alignment",_alignment);Field("Left indent (px)",_indent);Field("First-line indent (px)",_first);Field("Line spacing",_lines);Field("Before paragraph (px)",_before);Field("After paragraph (px)",_after);ColorField("Paragraph shading",_shade);ColorField("Paragraph border",_border);}
 private void ColorField(string label,TextBox box){var row=new DockPanel();var choose=new Button{Content="Choose…",Margin=new Thickness(8,0,0,0)};DockPanel.SetDock(choose,Dock.Right);row.Children.Add(choose);row.Children.Add(box);choose.Click+=async(_,_)=>{var color=await new OfficeColorWindow(label,box.Text).ShowDialog<ColorChoice?>(this);if(color!=null)box.Text=color.Color??"";};Field(label,row,"Blank uses no color.");}
 protected override ParagraphFormat Read(){foreach(var c in new[]{_shade.Text,_border.Text})if(!string.IsNullOrWhiteSpace(c)&&!Color.TryParse(c,out _))throw new ArgumentException("Enter a valid paragraph color.");return new ParagraphFormat{Alignment=_alignment.SelectedItem?.ToString()??"Left",Indent=(double)(_indent.Value??0),FirstLine=(double)(_first.Value??0),LineSpacing=(double)(_lines.Value??1.2m),Before=(double)(_before.Value??0),After=(double)(_after.Value??0),Shading=string.IsNullOrWhiteSpace(_shade.Text)?null:_shade.Text,Border=string.IsNullOrWhiteSpace(_border.Text)?null:_border.Text}.Checked();}
}
